 stopPsnPoll();psnBusy.value='save';psnError.value=''
 try{const data=await api('/admin/home/psn',{method:'PUT',version:attempt.version,key:attempt.key,body:body(attempt.payload)});if(stopped)return;applyPsn(data,true);psnNpsso.value='';pendingPsnSave=null;toast.success(t("PlayStation 设置已保存，凭据输入已清空。已保存的游戏不会因更新连接而删除。"))}catch(error){if(!stopped)psnWriteError(error)}finally{psnBusy.value='';schedulePsnPoll()}
}
async function syncPsn(){
 if(!psnReady.value||!psn.value?.connected||psnBusy.value||psnLoading.value||psnDirty.value||psnConflict.value||psnRunning.value||(psnPendingAction.value&&psnPendingAction.value!=='sync'))return
 pendingPsnSync||={key:randomID(),version:psnVersion.value};const attempt=pendingPsnSync;psnPendingAction.value='sync';stopPsnPoll();psnBusy.value='sync';psnError.value=''
 try{await api('/admin/home/psn/sync',{method:'POST',version:attempt.version,key:attempt.key,body:body({})});if(stopped)return;pendingPsnSync=null;psnPendingAction.value='';toast.info(t("同步请求已提交，正在读取处理状态。"))}catch(error){if(!stopped)psnWriteError(error)}finally{psnBusy.value='';if(!stopped&&!pendingPsnSync)await loadPsn(false,true);else schedulePsnPoll()}
}
async function disconnectPsn(){
 if(!psnReady.value||!psn.value?.connected||psnBusy.value||psnLoading.value||psnConflict.value||(psnPendingAction.value&&psnPendingAction.value!=='disconnect'))return
 if(!pendingPsnDisconnect&&!await confirmAction(t("断开 PlayStation 连接？"),t("将移除已保存的连接凭据并停止自动同步，本页未保存的 PlayStation 输入会放弃；现有游戏条目、封面与排序会保留。"),t("断开连接")))return
 pendingPsnDisconnect||={key:randomID(),version:psnVersion.value};const attempt=pendingPsnDisconnect;psnPendingAction.value='disconnect';stopPsnPoll();psnBusy.value='disconnect';psnError.value=''
 try{const data=await api('/admin/home/psn',{method:'PUT',version:attempt.version,key:attempt.key,body:body({auto_sync:false,disconnect:true})});if(stopped)return;applyPsn(data,true);psnNpsso.value='';pendingPsnDisconnect=null;toast.success(t("PlayStation 连接已断开，现有游戏条目已保留。"))}catch(error){if(!stopped)psnWriteError(error)}finally{psnBusy.value='';schedulePsnPoll()}
}
function psnVisibility(){if(document.hidden){stopPsnPoll();psnReadController?.abort()}else if(view.value==='steam')schedulePsnPoll()}
watch(view,value=>{stopPsnPoll();if(value==='steam'){psnPollFailures=0;void loadPsn(false,true)}else{psnReadSequence++;psnReadController?.abort();psnLoading.value=false}})

function beforeLeave(event:BeforeUnloadEvent){if(dirty.value||psnDirty.value||psnPendingAction.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void loadHome();void loadItems();void loadProjects();window.addEventListener('beforeunload',beforeLeave);document.addEventListener('visibilitychange',psnVisibility)})
onBeforeUnmount(()=>{stopped=true;sequence++;playlistSequence++;stopPsnPoll();psnReadSequence++;psnReadController?.abort();psnNpsso.value='';pendingPsnSave=null;pendingPsnSync=null;pendingPsnDisconnect=null;document.removeEventListener('visibilitychange',psnVisibility);listController?.abort();uploadController?.abort();resetCover();photos.value.forEach(release);window.removeEventListener('beforeunload',beforeLeave)})
</script>

<template>
 <div class="homepage-manager">
  <div class="homepage-topbar"><div class="homepage-tabs" role="tablist" :aria-label="t('首页管理分区')" @keydown="tabKey"><button v-for="tab in [{id:'content',label:t('页面内容')},{id:'walls',label:t('展示墙')},{id:'projects',label:t('项目卡片')},{id:'steam',label:t('游戏账号')}]" :id="uid+'-tab-'+tab.id" :key="tab.id" type="button" role="tab" :aria-selected="view===tab.id" :tabindex="view===tab.id?0:-1" :aria-controls="uid+'-panel-'+tab.id" @click="view=tab.id">{{tab.label}}</button></div><a class="button quiet" href="/" target="_blank" rel="noopener">{{t("查看首页")}}<Icon name="arrow" :size="16"/></a></div>

  <p v-if="homeError" class="homepage-feedback is-error" role="alert">{{homeError}} <button type="button" :disabled="locked||loadingHome" @click="loadHome(true)">{{homeConflict?t("载入最新设置"):t("重新载入设置")}}</button></p>
  <p v-if="loadingHome" class="homepage-loading" role="status">{{t("正在载入首页设置…")}}</p>
  <template v-if="ready">
   <section :id="uid+'-panel-content'" v-show="view==='content'" role="tabpanel" :aria-labelledby="uid+'-tab-content'">
    <form class="homepage-config-form" @submit.prevent="saveHome">
     <div class="homepage-config-grid"><section class="homepage-order" :aria-label="t('首页区块顺序')"><h2>{{t("显示与顺序")}}</h2><p class="homepage-help">{{t("从上到下依次展示。未开启的区块不会出现在首页。")}}</p><p class="homepage-scroll-hint">{{t("左右滑动可查看完整操作。")}}</p><div class="homepage-table-scroll" tabindex="0" :aria-label="t('首页区块表格，可横向滚动')"><table class="homepage-table homepage-sections-table"><thead><tr><th scope="col">{{t("区块")}}</th><th scope="col">{{t("显示")}}</th><th scope="col">{{t("顺序")}}</th><th scope="col">{{t("内容")}}</th></tr></thead><tbody><tr v-for="(key,index) in config.order" :id="uid+'-section-'+key" :key="key" tabindex="-1" :class="{'is-current':section===key}"><th scope="row">{{names[key]}}</th><td><label class="homepage-check"><input v-model="config.sections[key].enabled" type="checkbox" :disabled="locked"><span class="sr-only">{{t("显示{value1}", {value1:(names[key])})}}</span></label></td><td><div class="homepage-row-actions"><button type="button" :aria-label="t('将{value1}上移', {value1:names[key]})" :disabled="locked||index===0" @click="moveSection(index,-1)">{{t("上移")}}</button><button type="button" :aria-label="t('将{value1}下移', {value1:names[key]})" :disabled="locked||index===config.order.length-1" @click="moveSection(index,1)">{{t("下移")}}</button></div></td><td><button type="button" class="quiet" :aria-label="t('编辑{value1}内容', {value1:names[key]})" :aria-pressed="section===key" @click="editSection(key)">{{t("编辑")}}</button></td></tr></tbody></table></div></section>
     <section v-if="selectedSection" :id="uid+'-section-editor'" class="homepage-section-editor" tabindex="-1" :aria-label="t('{value1}设置', {value1:names[section]})"><h2>{{names[section]}}</h2><div class="homepage-fields"><label>{{section==='intro'?t("开场问候"):t("标题")}} <textarea v-model="selectedSection.title" rows="2" :disabled="locked"></textarea><small>{{t("最多80字符，支持换行。")}}</small></label><template v-if="section==='intro'"><label class="check"><input v-model="config.use_site_intro" type="checkbox" :disabled="locked">{{t("沿用网站姓名、简介与身份")}}</label><p class="homepage-help">{{t("网站介绍可在")}}<a href="/studio/settings#site">{{t("网站信息")}}</a>{{t("修改。关闭沿用后，为首页单独填写。")}}</p><template v-if="!config.use_site_intro"><label>{{t("首页姓名")}}<input v-model="config.intro_name" :disabled="locked"><small>{{t("最多80字符。")}}</small></label><label>{{t("身份与兴趣")}}<input v-model="roles" :disabled="locked" :placeholder="t('用顿号或逗号分隔')"><small>{{t("最多12项，每项60字符。")}}</small></label></template><label>{{t("卡片署名")}}<input v-model="config.intro_card_name" maxlength="80" :disabled="locked" :placeholder="t('留空沿用首页姓名')"><small>{{t("选填，最多80字符；仅用于首页卡片。")}}</small></label></template><label>{{section==='intro'?t("第二屏介绍"):t("介绍")}} <textarea v-model="selectedSection.description" rows="3" :disabled="locked||(section==='intro'&&config.use_site_intro)"></textarea><small>{{section==='intro'&&config.use_site_intro?t("当前沿用网站简介。"):t("最多600字符，支持换行。")}}</small></label><label v-if="['articles','steam','music','photos','projects'].includes(section)">{{t("显示数量")}}<input v-model.number="selectedSection.limit" type="number" min="0" :max="section==='articles'?12:24" :disabled="locked"><small>{{section==='articles'?t("0 隐藏文章区块，最多12篇。"):section==='steam'?t("首页最多5项，0隐藏；完整游戏墙展示全部。当前值超过5时，首页仍只显示5项。"):t("0 或没有可展示条目时隐藏该墙，最多24项。")}}</small></label><template v-if="section==='activity'">
       <SelectField v-model="config.activity.source" :label="t('统计来源')" :disabled="locked" :options="[{value:'posts_moments',label:t('公开文章与瞬间')},{value:'posts',label:t('仅公开文章')},{value:'moments',label:t('仅公开瞬间')}]"/>
       <SelectField v-model="config.activity.period" :label="t('时间范围')" :disabled="locked" :options="[{value:'rolling',label:t('最近365天')},{value:'year',label:t('按自然年')}]"/>
       <label v-if="config.activity.period==='year'">{{t("统计年份")}}<input v-model.number="config.activity.year" type="number" min="0" max="2100" :disabled="locked"><small>{{t("0 跟随当前年份；指定年份为2000至2100。")}}</small></label>
       <SelectField v-model="config.activity.timezone" :label="t('按此时区划分日期')" :disabled="locked" :options="activityZones"/>
       <p class="homepage-help">{{t("每篇目前公开的文章、每条公开瞬间，按首次发布时间计1次。草稿与编辑不增加次数，撤回或删除后不计入。绿色圆点反映博客发布频率。")}}</p>
       <button type="button" :disabled="locked||activityLoading" @click="previewActivity">{{activityLoading?t("正在读取…"):t("预览真实发布记录")}}</button>
       <p v-if="activityError" class="homepage-feedback is-error" role="alert">{{activityError}}</p>
       <div v-if="activityPreview" class="homepage-activity-preview"><p>{{t("{value1} — {value2} · {value3} 次发布 · {value4} 天有记录", {value1:(activityPreview.start),value2:(activityPreview.end),value3:(activityPreview.total),value4:(activityPreview.active_days)})}}</p><p v-if="activityChanged" class="homepage-help">{{t("统计设置已变化，重新预览可查看当前范围。")}}</p><div ref="activityScroll" class="homepage-activity-scroll" tabindex="0" :aria-label="t('真实发布频率预览，可横向滚动')"><div class="homepage-activity-grid"><div v-for="(week,wi) in activityPreview.weeks" :key="wi" class="homepage-activity-week"><span v-for="day in week" :key="day.date" :data-level="day.level" :data-in-range="day.in_range&&!day.future" :title="t('{value1}：{value2} 次发布', {value1:day.date,value2:day.count})" :aria-label="t('{value1}：{value2} 次发布', {value1:day.date,value2:day.count})"></span></div></div></div><p class="homepage-help">{{t("左右滑动查看更多日期；悬停或点击格子查看当天记录。")}}</p><p v-if="activityPreview.total===0" class="homepage-help">{{t("此范围内尚无符合来源的公开发布记录。")}}</p></div>
      </template><div class="homepage-field-pair"><label>{{t("链接文字")}}<input v-model="selectedSection.link_label" :disabled="locked"><small>{{section==='steam'?t("选填，留空显示“查看更多游戏”。"):t("选填，最多60字符。")}}</small></label><label>{{t("链接地址")}}<input v-if="section==='steam'" value="/games" readonly><input v-else v-model="selectedSection.link_url" :disabled="locked" :placeholder="t('/posts 或 https://…')"><small v-if="section==='steam'">{{t("查看更多固定进入 /games")}}</small></label></div></div></section></div>
     <details class="homepage-common"><summary>{{t("写作场景与滚动")}}</summary><div class="homepage-fields"><div class="homepage-field-pair"><label>{{t("写作标题")}}<textarea v-model="config.writing_title" rows="2" :disabled="locked"></textarea><small>{{t("最多80字符。")}}</small></label><label>{{t("写作介绍")}}<textarea v-model="config.writing_description" rows="3" :disabled="locked"></textarea><small>{{t("最多600字符。")}}</small></label></div><label>{{t("向下探索提示")}}<input v-model="config.scroll_label" :disabled="locked"><small>{{t("最多60字符。")}}</small></label><div class="homepage-checks"><label class="check"><input v-model="config.motion_enabled" type="checkbox" :disabled="locked">{{t("启用滚动视差")}}</label><label class="check"><input v-model="config.warmth_enabled" type="checkbox" :disabled="locked">{{t("滚动时渐变背景")}}</label></div></div></details>
     <div class="homepage-savebar"><span>{{homeDirty?t("有未保存的首页设置"):t("首页设置已保存")}}</span><button class="primary" :disabled="locked||!homeDirty||homeConflict">{{busy==='save-home'?t("正在保存…"):t("保存首页设置")}}</button></div>
    </form>
   </section>

   <section :id="uid+'-panel-walls'" v-show="view==='walls'" role="tabpanel" :aria-labelledby="uid+'-tab-walls'">
    <div class="homepage-wall-toolbar"><SelectField :model-value="kind" :label="t('展示墙')" :options="kinds" :disabled="locked||loadingItems" @update:model-value="changeKind"/><p class="homepage-help">{{kind==='steam'?t("公开展示同时用于首页和完整游戏墙；首页按设置数量与排序最多展示5项。"):t("首页展示数量在「页面内容」设置，不限制这里的分页内容库。")}}</p><button type="button" :disabled="locked" @click="editItem()">{{t("新建条目")}}</button><button v-if="kind==='photos'" :id="uid+'-photos-add'" type="button" :disabled="locked" @click="photoInput?.click()">{{t("选择多张照片")}}</button></div>
    <p v-if="listError" class="homepage-feedback is-error" role="alert">{{listError}} <button type="button" :disabled="locked||loadingItems" @click="loadItems()">{{t("刷新条目")}}</button></p>
    <div v-if="kind==='steam'" class="homepage-platform-filter" role="group" :aria-label="t('游戏平台')"><button v-for="option in [{value:'all',label:t('全部')},{value:'steam',label:'Steam'},{value:'psn',label:'PlayStation'}]" :key="option.value" type="button" :aria-pressed="gameFilter===option.value" :disabled="locked||loadingItems" @click="changeGameFilter(option.value as GameFilter)">{{option.label}}</button></div><div class="homepage-library-grid"><section class="homepage-library" :aria-label="t('展示墙条目')"><p class="homepage-scroll-hint">{{t("左右滑动可查看完整操作。")}}</p><div class="homepage-table-scroll" tabindex="0" :aria-label="t('展示墙条目表格，可横向滚动')" :aria-busy="loadingItems"><table class="homepage-table homepage-items-table"><thead><tr><th scope="col">{{t("图片 / 标题")}}</th><th scope="col">{{kind==='steam'?t("公开展示"):t("显示")}}</th><th scope="col">{{t("排序")}}</th><th scope="col">{{t("操作")}}</th></tr></thead><tbody><tr v-if="loadingItems"><td colspan="4" role="status">{{t("正在载入条目…")}}</td></tr><tr v-for="row in items" :key="row.id"><td><div class="homepage-item-cell"><img v-if="row.media_id||row.image_url" :src="row.media_id?'/media/'+row.media_id:row.image_url" :alt="row.alt||''" width="48" height="48" loading="lazy"><span v-else class="homepage-item-noimage"><Icon name="image" :size="20"/></span><div><strong>{{row.title}}</strong><span v-if="row.kind==='steam'" class="game-platforms"><span class="game-platform-badge">{{platformLabel(row)}}</span><span v-for="device in row.platforms||[]" :key="device" class="game-platform-device">{{device}}</span></span><small>{{row.subtitle||sourceLabel(row)}}</small><small v-if="row.local_override">{{t("已自定义，后续更新保留")}}</small><small v-if="row.kind==='steam'">{{row.playtime_minutes===null?t("时长未提供"):playtime(row.playtime_minutes)}}</small></div></div></td><td><label class="homepage-check"><input type="checkbox" :checked="row.visible" :disabled="locked||(item.id===row.id&&itemDirty)" :aria-label="(row.kind==='steam'?t('公开展示'):t('在首页显示'))+row.title" @change="toggleVisible(row,$event)"></label></td><td class="homepage-position">{{row.position}}</td><td><div class="homepage-row-actions"><button type="button" :disabled="locked" @click="editItem(row)">{{t("编辑")}}</button><button type="button" class="quiet danger" :disabled="locked" @click="deleteItem(row)">{{t("删除")}}</button></div></td></tr><tr v-if="!loadingItems&&!items.length&&!listError"><td colspan="4"><strong>{{t("还没有{value1}条目", {value1:(names[kind])})}}</strong><p class="homepage-help">{{t("添加自己的内容，保存后再决定是否显示。")}}</p></td></tr></tbody></table></div><InfiniteList :has-more="!!nextCursor" :loading="loadingItems" :disabled="locked" :error="listError" @load="loadItems(true)"/><p class="homepage-help">{{t("已显示 {value1} 项", {value1:(items.length)})}}</p></section>
     <form class="homepage-item-editor" @submit.prevent="saveItem"><div class="homepage-editor-heading"><h2>{{item.id?t("编辑条目"):t("新建条目")}}</h2><button type="button" class="quiet" :disabled="locked" @click="editItem()">{{t("新建")}}</button></div><p v-if="itemError" class="homepage-feedback is-error" role="alert">{{itemError}} <button v-if="itemConflict" type="button" :disabled="locked" @click="reloadItem">{{t("载入最新条目")}}</button></p>
      <details v-if="kind==='music'||(kind==='steam'&&gamePlatform(item)==='steam')" class="homepage-import"><summary>{{t("从{value1}链接读取信息", {value1:(kind==='steam'?'Steam':'Apple Music')})}}</summary>
       <label>{{kind==='steam'?t("商店链接或 App ID"):t("Apple Music 专辑或公开歌单链接")}}<input v-model="importInput" :disabled="locked" :placeholder="kind==='steam'?t('Steam 商店链接或 App ID'):t('粘贴完整专辑或公开歌单链接')"></label>
       <button type="button" :disabled="locked||!importInput.trim()" @click="importMetadata">{{busy==='import'||busy==='playlist-preview'?t("正在读取…"):isPlaylist?t("读取歌单预览"):t("读取链接信息")}}</button>
       <p v-if="importError" class="homepage-feedback is-error" role="alert">{{importError}}</p>
       <div v-if="importPreview&&!isPlaylist" class="homepage-import-preview"><img v-if="importPreview.image_url" :src="importPreview.image_url" :alt="t('平台封面预览')" width="64" height="64"><div><strong>{{importPreview.title}}</strong><p>{{importPreview.subtitle}}</p></div><button type="button" :disabled="locked" @click="useImport">{{t("用于新条目")}}</button></div>
       <template v-if="kind==='music'">
        <p v-if="playlistLoading" class="homepage-help" role="status">{{t("正在读取歌单导入状态…")}}</p>
        <div v-if="playlistStatus?.last_success_at" class="homepage-playlist-status"><strong>{{t("上次保存的歌单：{value1}", {value1:(playlistStatus.title)})}}</strong><p>{{t("{value1} 首已读取曲目 · {value2} 张去重专辑{value3}", {value1:(playlistStatus.track_count),value2:(playlistStatus.album_count),value3:(playlistStatus.partial?t(" · 未读取完整歌单"):'')})}}</p><small>{{t("保存于 {value1}", {value1:(date(playlistStatus.last_success_at))})}}</small><p v-if="playlistStatus.last_error" class="homepage-feedback is-error">{{playlistStatus.last_error}}</p></div>
        <p v-else-if="playlistStatus&&!playlistLoading" class="homepage-help">{{t("尚未保存歌单。读取预览后，核对本次内容并确认保存。")}}</p>
        <p v-if="playlistError" class="homepage-feedback is-error" role="alert">{{playlistError}}</p>
        <button v-if="playlistConflict||(!playlistStatus&&!playlistLoading)" type="button" :disabled="locked||playlistLoading" @click="loadPlaylistStatus">{{t("刷新导入状态")}}</button>
        <section v-if="playlistPreview" class="homepage-playlist-preview" :aria-label="t('本次歌单预览')">
         <h3>{{playlistPreview.title}}</h3><dl class="homepage-playlist-counts"><div><dt>{{t("本次读取曲目")}}</dt><dd>{{t("{value1} 首", {value1:(playlistPreview.track_count)})}}</dd></div><div><dt>{{t("本次去重专辑")}}</dt><dd>{{t("{value1} 张", {value1:(playlistPreview.album_count)})}}</dd></div><div><dt>{{t("当前预览专辑")}}</dt><dd>{{t("{value1} 张", {value1:(playlistPreview.preview_count)})}}</dd></div></dl>
         <p v-if="playlistPreview.partial" class="homepage-playlist-partial" role="status">{{t("未读取完整歌单，只保存本次已读取的部分。")}}</p>
         <p class="homepage-help">{{t("这里仅展示前 {value1} 张封面；确认后保存本次 {value2} 张去重专辑，包含当前未展示的已读取专辑。", {value1:(playlistPreview.preview_count),value2:(playlistPreview.album_count)})}}</p>
         <a class="homepage-playlist-source" :href="playlistPreview.source_url" target="_blank" rel="noopener">{{t("打开来源歌单")}}<Icon name="arrow" :size="16"/></a>
         <ol class="homepage-playlist-albums" tabindex="0" :aria-label="t('本次歌单专辑预览，可滚动')"><li v-for="(album,index) in playlistPreview.items" :key="album.provider_id||index"><img v-if="album.image_url" :src="album.image_url" :alt="t('{value1}封面', {value1:album.title})" width="64" height="64" loading="lazy"><strong>{{album.title}}</strong><small>{{album.subtitle}}</small></li></ol>
         <p v-if="playlistPreview.notice" class="homepage-help">{{playlistPreview.notice}}</p>
         <p class="homepage-help">{{t("预览有效至 {value1}。新导入专辑设为显示，已开启的音乐墙会按首页数量公开展示；已有手动、隐藏、排序和自选封面保留。", {value1:(date(playlistPreview.expires_at))})}}</p>
         <p v-if="playlistInputChanged" class="homepage-playlist-partial">{{t("链接已更改，当前仍是原歌单预览。重新读取后再确认保存。")}}</p>
         <p v-if="playlistExpired" class="homepage-playlist-partial">{{t("预览已过期，请重新读取；当前预览仍可查看。")}}</p>
