    <section v-if="kind==='photos'" class="homepage-photo-batch" :aria-label="t('批量上传照片')"><div class="homepage-editor-heading"><div><h2>{{t("多张照片")}}</h2><p class="homepage-help">{{t("依次上传，每张核对标题与说明后单独保存；不会自动公开。")}}</p></div><button type="button" :disabled="locked" @click="photoInput?.click()">{{t("继续添加照片")}}</button><input ref="photoInput" class="sr-only" type="file" multiple tabindex="-1" :aria-label="t('批量选择首页照片')" accept="image/jpeg,image/png,image/webp,image/gif" :disabled="locked" @change="pickPhotos"></div><ul v-if="photos.length" class="homepage-photo-queue"><li v-for="photo in photos" :id="uid+'-photo-'+photo.id" :key="photo.id" :data-upload-state="photo.state" tabindex="-1"><img v-if="photo.preview||photo.media_id" :src="photo.preview||'/media/'+photo.media_id" :alt="t('待核对照片')" width="56" height="56"><div><strong>{{photo.file.name}}</strong><span role="status">{{photo.state==='queued'?t("等待上传"):photo.state==='uploading'?t("正在上传…"):photo.state==='ready'?t("已上传，尚未保存"):photo.error}}</span><progress v-if="photo.state==='uploading'" :aria-label="t('正在上传照片')"></progress></div><div class="homepage-row-actions"><button v-if="photo.state==='ready'" type="button" :disabled="locked" @click="reviewPhoto(photo)">{{t("编辑并保存")}}</button><button v-if="photo.state==='failed'&&photo.retryable" type="button" :disabled="locked" @click="retryPhoto(photo)">{{t("重试")}}</button><button type="button" class="quiet danger" :disabled="!!busy||photo.state==='uploading'" @click="cancelPhoto(photo)">{{photo.state==='ready'?t("移除待保存项"):t("取消")}}</button></div></li></ul></section>
