      <template v-for="field in [{key:'title',label:t('标题'),max:80},{key:'description',label:t('简介'),max:600},{key:'url',label:t('项目链接'),max:2048},{key:'language',label:t('语言'),max:80}]" :key="field.key"><label v-if="project.source==='github'" class="check"><input v-model="project['custom_'+field.key]" type="checkbox" :disabled="locked">{{t("自定义{value1}", {value1:(field.label)})}}</label><label v-if="project.source==='manual'||project['custom_'+field.key]">{{field.label}}<textarea v-if="field.key==='description'" v-model="project[field.key]" rows="3" :disabled="locked"></textarea><input v-else v-model="project[field.key]" :disabled="locked"><small>{{t("最多{value1}字符{value2}", {value1:(field.max),value2:(project.source==='github'?t("；刷新保留此自定义内容。"):'')})}}</small></label></template>
