   <section :id="uid+'-panel-steam'" v-show="view==='steam'" role="tabpanel" :aria-labelledby="uid+'-tab-steam'">
    <form class="homepage-steam-form" @submit.prevent="saveHome"><h2>{{t("Steam 游戏同步")}}</h2><p class="homepage-help">{{t("填写自己的 Steam ID64 和 Web API Key。启用后每6小时尝试同步，资料是否可读取仍取决于 Steam 隐私设置。")}}</p><div class="homepage-fields"><label>Steam ID64<input v-model="steam.steam_id" inputmode="numeric" :disabled="locked" :placeholder="t('17位数字')"></label><label>Steam Web API Key<input v-model="apiKey" type="password" autocomplete="new-password" :disabled="locked" :placeholder="steamStatus.api_key_configured?t('已配置，留空保持'):t('尚未配置')" @input="clearKey=false"><small>{{steamStatus.api_key_configured?t("密钥已保存，不回显。"):t("保存密钥后才能同步。")}}</small></label><label v-if="steamStatus.api_key_configured" class="check"><input v-model="clearKey" type="checkbox" :disabled="locked" @change="clearKey&&(apiKey='')">{{t("移除已保存的 API Key")}}</label><SelectField v-model="steam.mode" :label="t('同步范围')" :disabled="locked" :options="[{value:'owned',label:t('已拥有游戏')},{value:'recent',label:t('最近游玩')}]"/><label class="check"><input v-model="steam.auto_sync_enabled" type="checkbox" :disabled="locked">{{t("每6小时自动同步")}}</label></div><div class="homepage-savebar"><span>{{homeDirty?t("有未保存的首页设置"):t("设置已保存")}}</span><button class="primary" :disabled="locked||!homeDirty||homeConflict">{{t("保存设置")}}</button></div></form><section class="homepage-steam-status" :aria-label="t('Steam 同步状态')"><h2>{{t("同步状态")}}</h2><dl><dt>API Key</dt><dd>{{steamStatus.api_key_configured?t("已配置"):t("未配置")}}</dd><dt>{{t("上次同步")}}</dt><dd>{{date(steamStatus.last_sync_at)}}</dd></dl><p v-if="steamStatus.last_error" class="homepage-feedback is-error">{{steamStatus.last_error}}</p><p class="homepage-help">{{dirty?t("先保存或放弃当前修改，再开始同步。"):!credentialsReady?t("先填写并保存 ID64 和 API Key。"):t("同步后可在展示墙调整显示、排序和自选封面。")}}</p><button type="button" :disabled="locked||dirty||!credentialsReady" @click="syncSteam">{{busy==='sync'?t("正在同步…"):t("立即同步")}}</button></section>
    <section class="homepage-psn-section" :aria-label="t('PlayStation 账号')">
     <h2>{{t("PlayStation 账号")}}</h2><p class="homepage-help">{{t("连接自己的 PSN 账号，将平台返回的游戏记录加入同一面游戏墙。时长、封面或链接未提供时会保留缺失状态，不按0或其他游戏代替。")}}</p>
     <p class="homepage-help">{{t("PlayStation 同步记录仅属于一个账号。同一账号更改 Online ID 后可以重新连接；换绑其他账号前，须先清理已有的 PlayStation 同步记录或由管理员维护。没有同步记录时可直接换绑。")}}</p>
     <p v-if="psnLoading" class="homepage-help" role="status">{{t("正在读取 PlayStation 状态…")}}</p>
     <p v-if="psnError" class="homepage-feedback is-error" role="alert">{{psnError}}</p>
     <button type="button" :disabled="!!psnBusy||psnLoading" @click="psnPollFailures=0;loadPsn(true)">{{t("载入最新 PlayStation 状态")}}</button>
     <template v-if="psnReady&&psn">
      <div class="homepage-psn-grid"><form class="homepage-psn-form" autocomplete="off" @submit.prevent="savePsn">
       <div class="homepage-fields"><label>{{t("用于核对的公开 Online ID（可选）")}}<input v-model="psnOnlineID" name="psn-online-id" autocomplete="off" :disabled="!!psnBusy||psnLoading" :placeholder="t('填写你自己的公开 Online ID')"><small>{{t("连接时核对账号身份；不需要填写 Sony 密码。")}}</small></label>
        <label :for="uid+'-psn-npsso'">{{t("NPSSO 凭据")}}<input :id="uid+'-psn-npsso'" v-model="psnNpsso" name="psn-npsso" type="password" autocomplete="off" autocapitalize="off" spellcheck="false" :disabled="!!psnBusy||psnLoading||!psnSecretAllowed" :placeholder="psn.connected?t('已连接，留空保持现有凭据'):t('仅在自己的后台填入')"><small>{{t("凭据只在本页临时输入，保存成功后清空，不回显或保存在浏览器本地。")}}</small></label>
        <p v-if="!psnSecretAllowed" class="homepage-help" role="status">{{t("请通过 HTTPS 后台连接；本地服务器可使用")}} <code>painter psn-connect --npsso-stdin</code> {{t("或")}} <code>--npsso-file</code>{{t("。此 HTTP 页面不接收新的 NPSSO 凭据。")}}</p><details class="homepage-psn-guide"><summary>{{t("如何取得自己的 NPSSO")}}</summary><ol><li>{{t("在自己的浏览器打开")}} <a href="https://www.playstation.com/acct/management/" target="_blank" rel="noopener noreferrer">{{t("Sony 官方账号页面")}}</a>{{t("并登录。")}}</li><li>{{t("打开")}} <a href="https://ca.account.sony.com/api/v1/ssocookie" target="_blank" rel="noopener noreferrer">{{t("Sony 官方凭据页面")}}</a>{{t("，复制其中的 npsso 字段。")}}</li><li>{{t("回到你自己的 Painter 后台填入并连接。NPSSO 是私密会话凭据，请勿分享到聊天或放进页面地址。")}}</li></ol><p class="homepage-help">{{t("这是手动凭据连接流程，不是公开 OAuth 授权；此后台不会要求你的 Sony 密码。")}}</p></details>
        <label class="check"><input v-model="psnAuto" type="checkbox" :disabled="!!psnBusy||psnLoading">{{t("自动同步 PlayStation 游戏")}}</label><p class="homepage-help">{{t("只影响后续更新；关闭自动同步或断开连接会保留已有游戏条目。")}}</p>
       </div><div class="homepage-savebar"><span>{{pendingPsnSave?t("上次保存结果尚未确认"):psnDirty?t("有未保存的 PlayStation 修改"):t("PlayStation 设置已保存")}}</span><button class="primary" :disabled="!!psnBusy||psnLoading||!psnDirty||psnConflict||!!(psnPendingAction&&psnPendingAction!=='save')||(!psnSecretAllowed&&!psn.connected)">{{psnBusy==='save'?t("正在保存…"):pendingPsnSave?t("重试上次保存"):psn.connected?t("保存 PlayStation 设置"):t("连接 PlayStation")}}</button></div>
      </form><section class="homepage-psn-status" :aria-label="t('PlayStation 同步状态')"><h3>{{t("连接与同步状态")}}</h3><dl><dt>{{t("连接")}}</dt><dd>{{psn.connected?t("已连接"):t("未连接")}}</dd><dt>Online ID</dt><dd>{{psn.online_id||t("未提供")}}</dd><dt>{{t("账号编号")}}</dt><dd>{{psn.account_id||t("未提供")}}</dd><dt>{{t("状态")}}</dt><dd>{{psn.status==='idle'&&!psn.connected?t("未连接"):psnStateLabels[psn.status]}}</dd><dt>{{t("游戏记录")}}</dt><dd>{{t("{value1} 条", {value1:(psn.game_count)})}}</dd><dt>{{t("上次同步")}}</dt><dd>{{date(psn.last_sync_at)}}</dd><dt>{{t("下次同步")}}</dt><dd>{{psn.next_sync_at?date(psn.next_sync_at):t("未安排")}}</dd></dl>
       <p v-if="psn.last_error" class="homepage-feedback is-error">{{psn.last_error}}</p><p v-if="psn.status==='reauth_required'" class="homepage-help">{{t("连接凭据已失效，请在左侧更新 NPSSO 后再同步。")}}</p><p v-else-if="psnRunning" class="homepage-help" role="status">{{t("{value1}此分区打开时会自动刷新状态。", {value1:(psn.status==='queued'?t("同步请求已排队。"):t("正在同步平台返回的游戏记录。"))})}}</p><p v-else class="homepage-help">{{psnDirty?t("先保存或放弃 PlayStation 修改，再开始同步。"):!psn.connected?t("先连接自己的 PlayStation 账号。"):t("同步完成后，可在展示墙调整条目的显示、排序和自选封面。")}}</p><div class="homepage-psn-actions"><button type="button" :disabled="!!psnBusy||psnLoading||!psn.connected||psnDirty||psnConflict||psnRunning||psn.status==='reauth_required'||!!(psnPendingAction&&psnPendingAction!=='sync')" @click="syncPsn">{{psnBusy==='sync'?t("正在提交…"):pendingPsnSync?t("重试同步请求"):t("同步 PlayStation 游戏")}}</button><button v-if="psn.connected" type="button" class="quiet danger" :disabled="!!psnBusy||psnLoading||psnConflict||!!(psnPendingAction&&psnPendingAction!=='disconnect')" @click="disconnectPsn">{{psnBusy==='disconnect'?t("正在断开…"):pendingPsnDisconnect?t("重试断开连接"):t("断开 PlayStation")}}</button></div>
      </section></div>
     </template>
    </section>
   </section>
  </template>
 </div>
</template>
